package com.cryptoloan.loan.adapters.out.persistence;import com.cryptoloan.loan.domain.model.LoanStatus;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;@Entity @Table(name="loans")class LoanJpaEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@Version long version;@Column(name="request_id",nullable=false,unique=true)UUID requestId;@Column(name="borrower_email",nullable=false,length=254)String borrowerEmail;@Column(name="borrower_name",nullable=false,length=120)String borrowerName;@Column(name="amount_eur",nullable=false,precision=19,scale=2)BigDecimal amountEur;@Column(name="collateral_symbol",nullable=false,length=40)String collateralSymbol;@Column(name="collateral_amount",nullable=false,precision=30,scale=10)BigDecimal collateralAmount;@Column(name="minimum_ratio",nullable=false,precision=10,scale=4)BigDecimal minimumRatio;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)LoanStatus status;@Column(name="warning_sent",nullable=false)boolean warningSent;@Column(name="last_observed_ratio",precision=12,scale=6)BigDecimal lastObservedRatio;@Column(name="created_at",nullable=false)Instant createdAt;@Column(name="approved_at")Instant approvedAt;@Column(name="liquidated_at")Instant liquidatedAt;@Column(name="contract_hash",length=64)String contractHash;}

